const { validateClassification } = (() => {
const module = { exports: {} };
'use strict';

// Holds model output to the classification contract in config/routing-rules.json.
//
// Shape only: is it JSON, are exactly the contract's fields present, are values of the right type
// and inside the enums. Whether the fields agree with one another is routing's concern, not this
// module's — contradictory output routes to NEEDS_REVIEW_CONTRADICTION rather than failing here.
//
// Never throws on bad output. Invalid output is a workflow state, CLASSIFICATION_FAILED, not a
// crash. Every error is collected rather than only the first, because the review queue shows them.
//
// Returns { ok: true, classification } or { ok: false, errors: [string] }.
// Pure: no n8n globals, no I/O.

const FIELDS = ['category', 'relevance', 'rationale', 'criteria', 'confidence'];

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function checkCriteria(criteria, contract, errors) {
  if (!isPlainObject(criteria)) {
    errors.push('criteria: expected an object');
    return;
  }
  for (const name of contract.criteria) {
    if (!(name in criteria)) {
      errors.push(`criteria.${name}: missing`);
    } else if (typeof criteria[name] !== 'boolean') {
      errors.push(`criteria.${name}: expected true or false`);
    }
  }
  for (const name of Object.keys(criteria)) {
    if (!contract.criteria.includes(name)) {
      errors.push(`criteria.${name}: not in the contract`);
    }
  }
}

function checkFields(value, contract, errors) {
  const categories = Object.keys(contract.categories);
  if ('category' in value && !categories.includes(value.category)) {
    errors.push(`category: expected one of ${categories.join(', ')}`);
  }
  if ('relevance' in value && !contract.relevance.includes(value.relevance)) {
    errors.push(`relevance: expected one of ${contract.relevance.join(', ')}`);
  }
  if ('rationale' in value && (typeof value.rationale !== 'string' || !value.rationale.trim())) {
    errors.push('rationale: expected a non-empty string');
  }
  if ('criteria' in value) {
    checkCriteria(value.criteria, contract, errors);
  }
  const { confidence } = value;
  if ('confidence' in value &&
      (typeof confidence !== 'number' || !(confidence >= 0 && confidence <= 1))) {
    errors.push('confidence: expected a number from 0 to 1');
  }
}

function validateClassification(output, contract) {
  let value = output;
  if (typeof output === 'string') {
    try {
      value = JSON.parse(output);
    } catch (error) {
      return { ok: false, errors: [`not valid JSON: ${error.message}`] };
    }
  }
  if (!isPlainObject(value)) {
    return { ok: false, errors: ['expected a JSON object'] };
  }
  const errors = [];
  for (const key of FIELDS) {
    if (!(key in value)) {
      errors.push(`${key}: missing`);
    }
  }
  for (const key of Object.keys(value)) {
    if (!FIELDS.includes(key)) {
      errors.push(`${key}: not in the contract`);
    }
  }
  checkFields(value, contract, errors);
  return errors.length === 0 ? { ok: true, classification: value } : { ok: false, errors };
}

module.exports = { validateClassification };

return module.exports;
})();

const { route, checkRules } = (() => {
const module = { exports: {} };
'use strict';

// Routes a validated classification using config/routing-rules.json.
//
// The only interpreter of that file. Rules are tried in order and the first whose conditions all
// hold wins; when none holds, the fallback applies. Order is load-bearing — see the file's notes.
//
// Confidence is a floor, not a key. When the rule that fired would decide a notice without a human
// (AUTO_MATCH or NOT_RELEVANT) and the model's confidence is below confidence_floor.min, the notice
// goes to the floor's review route instead. Confidence can hold a notice back for a person; it never
// moves one toward an automatic decision.
//
// The rules file is checked on every call, and a file that could route unsafely is refused rather
// than half-applied: an unknown field in a condition would otherwise make a rule silently never
// match. Input must already have passed validate-classification.js.
//
// Pure: no n8n globals, no I/O.

// Automatic routes, and the model verdict each one requires.
const AUTOMATIC = { AUTO_MATCH: 'match', NOT_RELEVANT: 'not_relevant' };
const REVIEW = ['NEEDS_REVIEW', 'NEEDS_REVIEW_CONTRADICTION'];

function checkCondition(contract, where, path, value) {
  if (path === 'relevance') {
    if (!contract.relevance.includes(value)) {
      throw new Error(`${where}: relevance "${value}" is not in the contract`);
    }
    return;
  }
  const name = path.startsWith('criteria.') ? path.slice('criteria.'.length) : null;
  if (!contract.criteria.includes(name)) {
    throw new Error(`${where}: unknown field "${path}"`);
  }
  if (typeof value !== 'boolean') {
    throw new Error(`${where}: "${path}" must be compared with true or false`);
  }
}

function checkReviewRoute(what, entry) {
  if (!entry || typeof entry.id !== 'string' || entry.id === '' || !REVIEW.includes(entry.route)) {
    throw new Error(`${what} must have an id and route to a review status`);
  }
}

function checkRules(config) {
  const { contract, rules, fallback, confidence_floor: floor } = config;
  const ids = new Set();
  for (const rule of rules) {
    const where = `rule "${rule.id}"`;
    if (typeof rule.id !== 'string' || rule.id === '' || ids.has(rule.id)) {
      throw new Error(`${where}: id must be a unique non-empty string`);
    }
    ids.add(rule.id);
    if (!(rule.route in AUTOMATIC) && !REVIEW.includes(rule.route)) {
      throw new Error(`${where}: unknown route "${rule.route}"`);
    }
    const conditions = Object.entries(rule.when || {});
    if (conditions.length === 0) {
      throw new Error(`${where}: has no conditions`);
    }
    for (const [path, value] of conditions) {
      checkCondition(contract, where, path, value);
    }
    const verdict = AUTOMATIC[rule.route];
    if (verdict && rule.when.relevance !== verdict) {
      throw new Error(
        `${where}: routing to ${rule.route} requires relevance "${verdict}" — ` +
          'a rule may narrow the model\'s verdict, never override it',
      );
    }
  }
  checkReviewRoute('fallback', fallback);
  checkReviewRoute('confidence_floor', floor);
  if (typeof floor.min !== 'number' || !(floor.min > 0 && floor.min <= 1)) {
    throw new Error('confidence_floor.min must be a number above 0 and at most 1');
  }
}

function valueAt(classification, path) {
  if (path === 'relevance') {
    return classification.relevance;
  }
  return classification.criteria[path.slice('criteria.'.length)];
}

// Returns { status, rule, rules_version } — rule is the id of the rule that fired, or of the
// confidence floor when it held the notice back, for the audit trail's "why was this routed".
function route(classification, config) {
  checkRules(config);
  const matched = config.rules.find((rule) => Object.entries(rule.when).every(
    ([path, value]) => valueAt(classification, path) === value,
  )) || config.fallback;
  const floor = config.confidence_floor;
  const decided = matched.route in AUTOMATIC && !(classification.confidence >= floor.min)
    ? floor
    : matched;
  return { status: decided.route, rule: decided.id, rules_version: config.version };
}

module.exports = { route, checkRules };

return module.exports;
})();

const { recordFor } = (() => {
const module = { exports: {} };
'use strict';

// Turns one Anthropic Messages API response into the object database/queries/record-classification.sql
// stores.
//
// The response is read as whatever came back. Only a message that ended normally (stop_reason
// end_turn) is validated; a refusal or a max_tokens stop can carry text that does not match the
// schema, and is CLASSIFICATION_FAILED with the reason. The classification is the first text block;
// thinking blocks come before it. Output that fails validate-classification.js is
// CLASSIFICATION_FAILED with its errors and raw text. Output that passes is routed by route.js.
//
// Returns null when there is no message at all: a call that still failed after n8n's retries and
// was passed on as an error item. Nothing is recorded, and recover.sql retries the claim later.
//
// Every record carries the notice text the model read, the envelope provenance of the MapleProcure
// response it came from, and the model that answered, as the response names it.
//
// validateClassification and route are passed in, so this file stands alone in a Code node.
// Pure: no n8n globals, no I/O.

const EMPTY_CLASSIFICATION = {
  routing_rule: null, category: null, relevance: null, rationale: null, criteria: null,
  model_confidence: null,
};

function recordFor(response, prepared, { rules, promptVersion }, { validateClassification, route }) {
  if (!response || response.type !== 'message' || !Array.isArray(response.content)) {
    return null;
  }
  const block = response.content.find((candidate) => candidate.type === 'text');
  const text = block && typeof block.text === 'string' ? block.text : null;
  const base = {
    model_name: response.model,
    prompt_version: promptVersion,
    rules_version: rules.version,
    notice_text: prepared.notice_text,
    ...prepared.envelope,
  };
  let result;
  if (response.stop_reason !== 'end_turn') {
    result = { ok: false, errors: [`the model stopped with stop_reason ${response.stop_reason}`] };
  } else if (text === null) {
    result = { ok: false, errors: ['the response has no text block'] };
  } else {
    result = validateClassification(text, rules.contract);
  }
  if (!result.ok) {
    return {
      ...base,
      ...EMPTY_CLASSIFICATION,
      routed_status: 'CLASSIFICATION_FAILED',
      validation_errors: result.errors,
      model_output_raw: text,
    };
  }
  const classification = result.classification;
  const routed = route(classification, rules);
  return {
    ...base,
    routed_status: routed.status,
    routing_rule: routed.rule,
    category: classification.category,
    relevance: classification.relevance,
    rationale: classification.rationale,
    criteria: classification.criteria,
    model_confidence: classification.confidence,
    validation_errors: null,
    model_output_raw: null,
  };
}

module.exports = { recordFor };

return module.exports;
})();

